query:
query SetupInputs($checkpoint: UInt53!, $upgradeDigest: String!, $upgradeCap: SuiAddress!, $legacyAdminCap: SuiAddress!, $registry: SuiAddress!,
  $registryType: String!, $adminCapType: String!) {
  checkpoint { sequenceNumber timestamp digest }
  genesis: checkpoint(sequenceNumber: 0) { sequenceNumber digest }
  reviewCheckpoint: checkpoint(sequenceNumber: $checkpoint) { sequenceNumber timestamp digest }
  upgradeTransaction: transaction(digest: $upgradeDigest) { digest sender { address } transactionBcs
  effects { status executionError { message }
  gasEffects { gasSummary { computationCost storageCost storageRebate nonRefundableStorageFee } }
  balanceChangesJson objectChanges(first: 50) { nodes { address idCreated idDeleted
  inputState { address version digest
  owner { __typename ... on AddressOwner { address { address } } ... on Shared { initialSharedVersion } }
  asMoveObject { contents { type { repr } json } } }
  outputState { address version digest
  owner { __typename ... on AddressOwner { address { address } } ... on Shared { initialSharedVersion } }
  asMoveObject { contents { type { repr } json } } asMovePackage { address version linkage { originalId upgradedId version }
  typeOrigins { module struct definingId }
  modules(first: 50) { nodes { name bytes } pageInfo { hasNextPage endCursor } } } }
} pageInfo { hasNextPage endCursor } } checkpoint { sequenceNumber timestamp } }
}
  upgradeCap: object(address: $upgradeCap) { address version digest
  owner { __typename ... on AddressOwner { address { address } } ... on Shared { initialSharedVersion } }
  asMoveObject { contents { type { repr } json } }
  previousTransaction { digest effects { status checkpoint { sequenceNumber timestamp } } } }
  legacyAdminCap: object(address: $legacyAdminCap) { address version digest
  owner { __typename ... on AddressOwner { address { address } } ... on Shared { initialSharedVersion } }
  asMoveObject { contents { type { repr } json } }
  previousTransaction { digest effects { status checkpoint { sequenceNumber timestamp } } } }
  registry: object(address: $registry) { address version digest
  owner { __typename ... on AddressOwner { address { address } } ... on Shared { initialSharedVersion } }
  asMoveObject { contents { type { repr } json } }
  previousTransaction { digest effects { status checkpoint { sequenceNumber timestamp } } } }
  registries: objects(first: 2, filter: { type: $registryType }) {
    nodes { address version digest
  owner { __typename ... on AddressOwner { address { address } } ... on Shared { initialSharedVersion } }
  asMoveObject { contents { type { repr } json } }
  previousTransaction { digest effects { status checkpoint { sequenceNumber timestamp } } } } pageInfo { hasNextPage endCursor }
  }
  adminCaps: objects(first: 2, filter: { type: $adminCapType }) {
    nodes { address version digest
  owner { __typename ... on AddressOwner { address { address } } ... on Shared { initialSharedVersion } }
  asMoveObject { contents { type { repr } json } }
  previousTransaction { digest effects { status checkpoint { sequenceNumber timestamp } } } } pageInfo { hasNextPage endCursor }
  }
}
